// Judge occasionally emits an off-by-one matched_gold_index (== goldAtoms.length)
// while its reason names the real index; recover it so the confirmed match
// isn't left in unmatched_gold_indices as a false recall miss.
for (const v of parsed.extracted_verdicts) {
  if (v.verdict !== 'matches_gold') continue;
  const idx = v.matched_gold_index;
  if (typeof idx === 'number' && Number.isInteger(idx) && idx >= 0 && idx < goldAtoms.length) continue;
  let recovered: number | null = null;
  const nums = [...String(v.reason ?? '').matchAll(/(?:index\s*|gold\s*(?:atom\s*)?(?:#|\[)?\s*|\[)(\d+)/gi)];
  for (const m of nums) {
    const n = Number(m[1]);
    if (n < goldAtoms.length) recovered = n;
  }
  v.matched_gold_index = recovered;
  if (recovered !== null) {
    parsed.unmatched_gold_indices = parsed.unmatched_gold_indices.filter(i => i !== recovered);
  }
}

